package net.officefloor.hq.app.invoices;

import jakarta.persistence.Column;
import jakarta.persistence.Entity;
import jakarta.persistence.GeneratedValue;
import jakarta.persistence.GenerationType;
import jakarta.persistence.Id;
import jakarta.persistence.Table;
import java.math.BigDecimal;
import java.math.RoundingMode;

/**
 * One line of an invoice: a quantity (up to two decimals) times a unit price, less the line's own
 * percentage discount.
 */
@Entity
@Table(name = "invoice_line")
public class InvoiceLine {

    @Id
    @GeneratedValue(strategy = GenerationType.IDENTITY)
    private Long id;

    private String description;

    private BigDecimal qty;

    @Column(name = "unit_price")
    private BigDecimal unitPrice;

    /** Whether the line is left out of the taxed amount, e.g. postage. */
    @Column(name = "tax_exempt")
    private boolean taxExempt;

    /** The line's own percentage discount, 0 to 100 with up to two decimals; 0 is none. */
    @Column(name = "discount_pct")
    private BigDecimal discountPct = BigDecimal.ZERO;

    /** The line's own tax percentage, 0 to 100 with up to two decimals; null uses the workspace rate. */
    @Column(name = "tax_rate")
    private BigDecimal taxRate;

    /** The id of the invoice line this credit note line credits; null when it credits no line in particular. */
    @Column(name = "credit_of_line")
    private Long creditOfLine;

    /** The unit type the line is billed in (hour, day, ...); null for none. */
    @Column(name = "unit_type")
    private String unitType;

    protected InvoiceLine() {
    }

    public InvoiceLine(String description, BigDecimal qty, BigDecimal unitPrice, boolean taxExempt,
            BigDecimal discountPct, BigDecimal taxRate) {
        this.description = description;
        this.qty = qty;
        this.unitPrice = unitPrice;
        this.taxExempt = taxExempt;
        this.discountPct = discountPct;
        this.taxRate = taxRate;
    }

    public InvoiceLine(String description, BigDecimal qty, String unitType, BigDecimal unitPrice, boolean taxExempt,
            BigDecimal discountPct, BigDecimal taxRate) {
        this(description, qty, unitPrice, taxExempt, discountPct, taxRate);
        this.unitType = unitType;
    }

    /** A new line with the same description, quantity, unit type, price, discount, tax rate and exemption. */
    public InvoiceLine copy() {
        return new InvoiceLine(description, qty, unitType, unitPrice, taxExempt, discountPct, taxRate);
    }

    /** A new credit note line crediting this line, with its description, quantity, price, discount, tax rate and exemption. */
    public InvoiceLine creditCopy() {
        InvoiceLine credit = copy();
        credit.creditOfLine = id;
        return credit;
    }

    /** Changes the line's description, quantity, price, discount, tax rate and exemption; they have already been checked. */
    public void update(String description, BigDecimal qty, String unitType, BigDecimal unitPrice, boolean taxExempt,
            BigDecimal discountPct, BigDecimal taxRate) {
        this.description = description;
        this.unitType = unitType;
        this.qty = qty;
        this.unitPrice = unitPrice;
        this.taxExempt = taxExempt;
        this.discountPct = discountPct;
        this.taxRate = taxRate;
    }

    public Long getId() {
        return id;
    }

    public String getDescription() {
        return description;
    }

    public BigDecimal getQty() {
        return qty;
    }

    public String getUnitType() {
        return unitType;
    }

    public BigDecimal getUnitPrice() {
        return unitPrice;
    }

    public boolean isTaxExempt() {
        return taxExempt;
    }

    public BigDecimal getDiscountPct() {
        return discountPct;
    }

    public BigDecimal getTaxRate() {
        return taxRate;
    }

    public Long getCreditOfLine() {
        return creditOfLine;
    }

    /** The rate the line is taxed at: its own rate, or the given workspace rate when it has none. */
    public BigDecimal taxRate(BigDecimal workspaceRate) {
        return taxRate == null ? workspaceRate : taxRate;
    }

    /**
     * Quantity times unit price, rounded half up to the given number of decimals (2, the cent; 0 for
     * whole yen), before the line's discount.
     */
    public BigDecimal grossAmount(int scale) {
        return qty.multiply(unitPrice).setScale(scale, RoundingMode.HALF_UP);
    }

    /** The line's discount: its percentage of the gross amount, rounded down to the given number of decimals. */
    public BigDecimal discount(int scale) {
        return grossAmount(scale).multiply(discountPct).divide(BigDecimal.valueOf(100))
                .setScale(scale, RoundingMode.DOWN);
    }

    /** The line amount, to the given number of decimals: the gross amount less the line's discount. */
    public BigDecimal amount(int scale) {
        return grossAmount(scale).subtract(discount(scale));
    }
}
        }
        return amount;
    }

    /** The currency the client is billed in; US dollars when there is no such client. */
    private Currency currencyOf(Long clientId) {
        return clients.findById(clientId).map(Client::getCurrency).orElse(Currency.USD);
    }

    /**
     * Refuses an amount entered with more decimals than the currency has: whole yen for a yen client
     * (the cent is already checked for the rest).
     */
    /**
     * A line's unit price: the one entered, or else the client's rate for the line's unit type.
     * Refused when neither is there.
     */
    private BigDecimal linePrice(Invoice invoice, String unitType, BigDecimal unitPrice) {
        if (unitPrice != null) {
            return unitPrice;
        }
        if (unitType == null) {
            throw new InvoiceRejectedException("Enter a unit price or a unit type.");
        }
        Client client = clients.findById(invoice.getClientId()).orElse(null);
        BigDecimal rate = client == null ? null : client.rateFor(unitType);
        if (rate == null) {
            throw new InvoiceRejectedException("The client's rate card has no rate for " + unitType
                    + "; enter a unit price.");
        }
        return rate;
    }

    private static void requireWhole(Currency currency, BigDecimal amount, String what) {
        if (amount != null && !currency.isWhole(amount)) {
            throw new InvoiceRejectedException(what + " must be in whole yen, with no decimals.");
        }
    }

    /** The RF reference of each of the client's drafts, to its invoice id. */
    private Map<String, Long> draftsByReference(Long clientId) {

    /**
     * The client's tax number, without spaces (see {@link TaxNumber}): with a valid one and a region
     * outside the workspace's home region its invoices are reverse charged; null for no number.
     */
    @Column(name = "tax_number")
    private String taxNumber;

    /** The client's rate card: its price per unit type (hour, day, ...); empty for none. */
    @ElementCollection(fetch = FetchType.EAGER)
    @CollectionTable(name = "client_rate", joinColumns = @JoinColumn(name = "client_id"))
    @MapKeyColumn(name = "unit_type")
    @Column(name = "unit_price")
    private Map<String, BigDecimal> rates = new TreeMap<>();

    /** The highest late-interest rate a client can be given, as a percentage. */
    public static final int MAX_INTEREST_RATE = 30;

    /** The longest grace period a client can be given, in days. */
    public static final int MAX_GRACE_DAYS = 30;

    protected Client() {
    }

    public Client(String name, String email, Integer termsDays, BigDecimal discountPct, boolean taxExempt,
            Currency currency, BigDecimal earlyPayPct, Integer earlyPayDays, BigDecimal retentionPct,
            Integer graceDays, BigDecimal interestRate, String region, String taxNumber) {
        this.name = name;
        this.email = email;
        this.termsDays = termsDays;
        this.discountPct = discountPct == null ? BigDecimal.ZERO : discountPct;
        this.taxExempt = taxExempt;
        this.currency = currency == null ? Currency.USD : currency;
        this.earlyPayPct = earlyPayPct == null ? BigDecimal.ZERO : earlyPayPct;
        this.earlyPayDays = earlyPayDays;
        this.retentionPct = retentionPct == null ? BigDecimal.ZERO : retentionPct;
        this.graceDays = graceDays == null ? Invoice.GRACE_DAYS : graceDays;
        this.interestRate = interestRate;
        this.region = region;
        this.taxNumber = taxNumber;
    }

    public Long getId() {
        return id;
    }

    public String getName() {
        return name;
    }

    public String getEmail() {
        return email;
    }

    public Integer getTermsDays() {
        return termsDays;
    }

    public BigDecimal getDiscountPct() {
        return discountPct;
    }

    public boolean isTaxExempt() {
        return taxExempt;
    }

    public Currency getCurrency() {
        return currency;
    }

    public BigDecimal getEarlyPayPct() {
        return earlyPayPct;
    }

    public Integer getEarlyPayDays() {
        return earlyPayDays;
    }

    public BigDecimal getRetentionPct() {
        return retentionPct;
    }

    public int getGraceDays() {
        return graceDays;
    }

    public BigDecimal getInterestRate() {
        return interestRate;
    }

    public String getRegion() {
        return region;
    }

    public String getTaxNumber() {
        return taxNumber;
    }

    public Map<String, BigDecimal> getRates() {
        return rates;
    }

    /** The client's price for the given unit type (matched ignoring case and surrounding spaces); null when not on its card. */
    public BigDecimal rateFor(String unitType) {
        if (unitType == null) {
            return null;
        }
        return rates.entrySet().stream().filter(r -> r.getKey().equalsIgnoreCase(unitType.trim()))
                .map(Map.Entry::getValue).findFirst().orElse(null);
    }
}

